import csv,json,re,subprocess
from decimal import Decimal as D
from pathlib import Path
root=Path('/work/workspace');deliver=root/'deliverable';docs=root/'documents'
fail=[]
def check(cond,msg):
 if not cond:fail.append(msg)
def rd(p):
 with p.open(newline='') as f:return list(csv.DictReader(f))
def cashnum(s):
 return -D(re.sub(r'[,"'$()]'"','',s)) if '(' in s else D(re.sub(r'[,"'$()]'"','',s))
opening={x['account']:D(x['debit'])-D(x['credit']) for x in rd(docs/'opening_trial_balance.csv')}
prior=opening
for month in range(1,13):
 tag=f'{month:02d}';dp=deliver/f'month_{tag}';src=docs/f'month_{tag}'
 check(all((dp/n).exists() for n in ['journal_entries.json','trial_balance.json','deferred_revenue_rollforward.json','bank_reconciliation.md','open_items.md']),f'{tag} missing file')
 e=json.loads((dp/'journal_entries.json').read_text());tb=json.loads((dp/'trial_balance.json').read_text())['accounts'];rf=json.loads((dp/'deferred_revenue_rollforward.json').read_text())
 byacct={}
 for j in e:
  check(sum(D(str(l['debit']))-D(str(l['credit'])) for l in j['lines'])==0,f'{tag} JE {j[\"ref\"]} unbalanced')
  for l in j['lines']:byacct[l['account']]=byacct.get(l['account'],D(0))+D(str(l['debit']))-D(str(l['credit']))
 ending={a:D(str(v['debit']))-D(str(v['credit'])) for a,v in tb.items()}
 for a in set(prior)|set(ending)|set(byacct):check(ending.get(a,D(0))==prior.get(a,D(0))+byacct.get(a,D(0)),f'{tag} TB movement {a}')
 check(sum(ending.values())==0,f'{tag} TB imbalance')
 check(-ending['2200']==-D(str(rf['total']['closing'])),f'{tag} deferred TB mismatch')
 check(D(str(rf['total']['opening']))+D(str(rf['total']['billed']))-D(str(rf['total']['recognized']))==D(str(rf['total']['closing'])),f'{tag} deferred roll total')
 check(sum(D(str(x['closing'])) for x in rf['contracts'].values())+D(str(rf['unallocated_opening_deferred_revenue']['closing']))==D(str(rf['total']['closing'])),f'{tag} contract closings')
 inv=rd(src/'invoices.csv');rec=rd(src/'cash_receipts.csv');bills=rd(src/'vendor_bills.csv');pay=json.loads((src/'payroll_register.json').read_text())
 for i in inv:
  v=next((x for x in e if x['ref']=='BILL-'+i['invoice']),None)
  check(v is not None,f'{tag} invoice omitted {i[\"invoice\"]}')
  if v:check(sum(D(str(l['debit'])) for l in v['lines'])==D(i['amount']),f'{tag} invoice wrong {i[\"invoice\"]}')
 for i in rec:
  v=next((x for x in e if x['ref']=='RCPT-'+i['applied_to']),None)
  check(v is not None,f'{tag} receipt omitted {i[\"applied_to\"]}')
  if v:check(sum(D(str(l['debit'])) for l in v['lines'])==D(i['amount']),f'{tag} receipt wrong {i[\"applied_to\"]}')
 check(sum(D(x['amount']) for x in bills)==sum(D(str(l['debit'])) for j in e if j['ref'].startswith('VB-') for l in j['lines'] if l['account'] not in ['2000']),f'{tag} vendor costs')
 check(D(pay['gross'])+D(pay['employer_taxes_benefits'])==D(pay['net_pay'])+D(pay['taxes_remitted']),f'{tag} payroll register arithmetic')
 check(byacct.get('5900',D(0))==D('1777.78'),f'{tag} depreciation')
 check(D(str(rf['total']['opening']))==(-prior.get('2200',D(0))-(D(15000) if month==7 else D(0))),f'{tag} deferred opening bridge')
 pdf=subprocess.check_output(['pdftotext','-layout',str(src/'bank_statement.pdf'),'-'],text=True)
 summary=re.search(r'Beginning balance\\s+Total debits\\s+Total credits\\s+Ending balance\\s+([("'$0-9,.)]+)'"\\s+([("'$0-9,.)]+)'"\\s+([("'$0-9,.)]+)'"\\s+([("'$0-9,.)]+)'"',pdf)
 check(summary is not None,f'{tag} PDF summary parse')
 if summary:
  begin,debits,credits,bankend=map(cashnum,summary.groups())
  check(begin-debits+credits==bankend,f'{tag} PDF arithmetic')
  check(ending.get('1000',D(0))-(-ending.get('2010',D(0)))==bankend,f'{tag} net bank TB')
  check(D(str(sum(D(x['amount']) for x in rec)))+ (D(48200) if month==5 else D(0)) == credits,f'{tag} bank credits')
  check(sum(D(x['amount']) for x in bills)+D(pay['net_pay'])+D(pay['taxes_remitted'])+(D(48200) if month==4 else D(0))==debits,f'{tag} bank debits')
 check((dp/'bank_reconciliation.md').read_text().find('Difference: "'$0.00'"')>=0,f'{tag} bank rec difference text')
 print(tag,'bank',ending.get('1000',0)+ending.get('2010',0),'deferred',-ending['2200'],'revenue delta',-byacct.get('4000',0),'issues',len(fail))
 prior=ending
# Citation targets from all delivered markdown must resolve to one of the indexed library items.
allowed={root/'library'/n for n in ['asc606_excerpts.md','asc250_excerpts.md','revenue_policy_memo.md','close_checklist.md']}
for path in deliver.rglob('*.md'):
 for target in re.findall(r'\\]\\((["'^)]+)'"\\)',path.read_text()):
  resolved=(path.parent/target).resolve()
  check(resolved in allowed,f'unsupported citation {path}: {target}')
print('FAILURES:',len(fail))
for x in fail:print(x)
